package com.example.blades360;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Isolated guide/filter fixtures. Existing playlist and preferences are never changed. */
public final class IptvGuideInstrumentation extends Instrumentation {
 int checks;MainActivity a;IptvClient saved,test;IptvBrowser b;String session="blades360-guide-test";
 void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 void ui(Runnable run){runOnMainSync(run);}
 IptvData.Channel channel(String name,String group){IptvData.Channel c=new IptvData.Channel();c.id=name;c.tvg=name;c.name=name;c.group=group;c.url="http://127.0.0.1:1/test.m3u8";return c;}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{
  IptvData.Channel english=channel("EN: News HD","US | News"),french=channel("[FR] Culture","France"),plain=channel("US Open Tennis","Sport");check(IptvLabels.tags(english).containsAll(Arrays.asList("EN","US")),"EN and US labels stay distinct");check(IptvLabels.tags(french).contains("FR"),"Bracketed country label");check(IptvLabels.tags(plain).contains("OTHER"),"Words in channel titles do not infer country");check(IptvLabels.tags(channel("ITV 1","UK | Entertainment")).equals(Collections.singleton("UK")),"ITV is not Italian");check(IptvLabels.tags(channel("Station","DE - German")).contains("DE"),"Dash separated group");
  IptvData.Channel parsed=IptvData.playlist("#EXTM3U\n#EXTINF:-1 tvg-language=\"English\" tvg-country=\"USA\",Station\nhttps://example.invalid/stream.ts", "https://example.invalid/list.m3u").channels.get(0);check(IptvLabels.tags(parsed).containsAll(Arrays.asList("EN","US")),"Explicit playlist metadata");check(IptvData.Channel.from(parsed.json()).language.equals("English"),"Language metadata survives cache");
  CountDownLatch loaded=new CountDownLatch(1);ui(()->{if(a.bootAnimation!=null)a.bootAnimation.finish();saved=a.iptv;test=new IptvClient(a,"iptv-guide-test");test.changed=loaded::countDown;});check(loaded.await(10,TimeUnit.SECONDS),"Isolated cache loaded");
  ui(()->{test.channels.add(english);test.channels.add(french);test.channels.add(plain);test.toggleLabel("FR");check(test.visibleChannels().size()==2,"Hide matching label");check(test.channels.size()==3,"Hidden channels not deleted");test.toggleLabel("US");check(test.visibleChannels().size()==1,"Union of hidden labels");test.showAllLabels();check(test.visibleChannels().size()==3,"Show all restores channels");test.toggleLabel("OTHER");check(!test.visible(plain),"Unlabelled visibility is explicit");test.showAllLabels();test.channels.clear();
   String[] names={"US: World News HD","EN: Discovery Science","UK: Cinema Select","FR: Culture HD","ES: Sports One","DE: Nature UHD","US: Family Movies","EN: Music Live","CA: Local News"};String[] titles={"Morning Report","Beyond the Solar System","The Grand Journey","Arts & Ideas","Matchday Live","Wild Horizons","Family Matinee","Studio Sessions","Around the City"};long start=System.currentTimeMillis()/1800000*1800000;
   for(int n=0;n<names.length;n++){IptvData.Channel c=channel(names[n],names[n].substring(0,2)+" | Sample channels");test.channels.add(c);for(int i=-2;i<8;i++){IptvData.Programme p=new IptvData.Programme();p.channel=c.tvg;p.title=i==0?titles[n]:i==1?"Up Next: "+titles[(n+1)%titles.length]:titles[(n+i+9)%titles.length];p.description="Guide layout test · Sample programme. Explore the stories, people and places behind today's headlines. This programme description demonstrates the Blades guide information panel.";p.start=start+i*1800000;p.end=p.start+1800000;test.programmes.add(p);}}test.programmes.sort(Comparator.comparingLong(p->p.start));test.indexGuide();a.iptv=test;a.openIptv();b=a.iptvBrowser;b.openGuide();});
  waitForIdleSync();Thread.sleep(500);
  ui(()->{IptvGuide g=b.guide;check(g.channels.size()==9,"Guide includes visible channels");check(g.selectedProgramme()!=null,"Guide selects current programme");long before=g.selectedTime;g.moveTime(1);check(g.selectedTime>before,"Right selects next programme");g.shift(IptvGuide.DAY);check(g.window>System.currentTimeMillis(),"Day navigation");g.now();check(Math.abs(g.selectedTime-System.currentTimeMillis())<1000,"Y returns to now");g.moveChannel(8);check(g.offset>0&&g.index==8,"Guide scroll follows selected row");g.moveChannel(-8);test.toggleLabel("FR");check(g.channels.size()==8,"Filter refresh updates open guide");b.page(1);check(b.rows.stream().noneMatch(row->row.title.startsWith("FR")),"Groups exclude hidden channels");b.page(2);check(b.visible.size()==8,"Channel lists exclude hidden channels");test.showAllLabels();g.now();g.select();check(g.actions,"Programme detail actions");g.back();check(!g.actions,"B closes detail actions");});
  waitForIdleSync();Thread.sleep(300);Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),"epg-layout-test.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();}
  Object[] response={null};CountDownLatch mediaReady=new CountDownLatch(1);ui(()->a.jellyfin.get("/Items?UserId="+a.jellyfin.user()+"&Recursive=true&IncludeItemTypes=Movie&Limit=1&Fields=MediaSources",v->{response[0]=v;mediaReady.countDown();}));check(mediaReady.await(25,TimeUnit.SECONDS)&&response[0] instanceof JSONObject,"Local preview media available");JSONObject movie=((JSONObject)response[0]).getJSONArray("Items").getJSONObject(0);String id=movie.getString("Id"),source=movie.getJSONArray("MediaSources").getJSONObject(0).getString("Id");
  Map<String,String> headers=a.jellyfin.headers();ui(()->{IptvData.Channel c=b.guide.selected();c.url=a.jellyfin.server()+"/Videos/"+id+"/master.m3u8?MediaSourceId="+source+"&VideoCodec=h264&AudioCodec=aac&VideoBitrate=1500000&AudioBitrate=128000&MaxWidth=854&TranscodingMaxAudioChannels=2&SegmentContainer=ts&MinSegments=2&DeviceId=blades360-tablet&PlaySessionId="+session;c.headers=headers;b.guide.togglePreview();});boolean[] ready={false};for(int i=0;i<50;i++){ui(()->ready[0]=b.guide.preview!=null&&b.guide.preview.getPlaybackState()==androidx.media3.common.Player.STATE_READY);if(ready[0])break;Thread.sleep(500);}check(ready[0],"Embedded preview decodes video");
  ui(()->{b.guide.watch();check(b.guide.preview==null&&!b.guide.previewEnabled,"Preview released before full-screen player");check(b.player!=null,"Guide launches full-screen playback");b.player.close();check(b.guide.getVisibility()==View.VISIBLE,"Back restores guide");b.guide.togglePreview();b.guide.stopPreview();check(b.guide.preview==null&&!b.guide.previewEnabled,"Background stop cancels pending preview");b.guide.close();check(b.guide==null,"Guide releases on exit");});result.putString("stream","PASS: "+checks+" EPG and filter checks");
 }catch(Throwable e){result.putString("stream","FAIL: "+e.getClass().getSimpleName()+": "+e.getMessage());}finally{ui(()->{if(b!=null&&!b.closed)b.close(false);if(test!=null){test.close();a.getSharedPreferences("iptv-guide-test_options",0).edit().clear().commit();}if(saved!=null)a.iptv=saved;a.jellyfin.stopEncoding(session);});}finish(result.getString("stream").startsWith("PASS")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
